package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MaxSeriesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property max series of observed source ")
  void test_max_series_v_o_builder() {
    Assertions.assertFalse(MaxSeriesVO.nullValue().getMaxSeries().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MaxSeriesVO.tryFrom(null).getMaxSeries().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, MaxSeriesVO.from(1).getMaxSeries().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MaxSeriesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", MaxSeriesVO.from(1).toString());
  }
}
